using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.AI;using UnityEditor;using FireSafety;
public static class AuditSchool { public static string Run(){var checks=new List<object>();void Check(string n,bool p,object e=null)=>checks.Add(new{name=n,pass=p,evidence=e});var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var replicas=all.Where(t=>t.name.EndsWith(" - environment only")).ToArray();Check("Exactly one original and four environment classrooms",replicas.Length==4&&GameObject.Find("Classroom - licensed source art"));Check("Replicas contain no gameplay behaviours",replicas.All(t=>t.GetComponentsInChildren<MonoBehaviour>(true).All(c=>c.GetType().Namespace!="FireSafety")));Check("No missing scripts",all.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject))==0);var renderers=all.Select(t=>t.GetComponent<Renderer>()).Where(r=>r).ToArray();var bad=renderers.Where(r=>r.sharedMaterials.Any(m=>!m||m.shader.name.Contains("InternalError"))).Select(r=>r.name).ToArray();Check("No missing or error-shader materials",bad.Length==0,bad);
var nav=UnityEngine.Object.FindAnyObjectByType<NavigationManager>();var routes=new List<object>();foreach(float z in new[]{0f,-17.1f,-8.55f,8.55f,17.1f}){var p=new Vector3(0,.05f,-1.95f+z);nav.Recalculate(p);var path=new NavMeshPath();NavMeshHit h;bool sampled=NavMesh.SamplePosition(p,out h,.4f,NavMesh.AllAreas);bool complete=sampled&&NavMesh.CalculatePath(h.position,nav.assembly.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete;routes.Add(new{z,complete,guidance=nav.Available,corners=path.corners.Select(v=>v.ToString()).ToArray()});Check("Classroom at z="+z+" has a connected collision-checked route",complete&&nav.Available);}
var crowd=UnityEngine.Object.FindAnyObjectByType<SchoolEvacuationController>();Check("One teacher and ten students",crowd.people.Length==11&&crowd.people.Count(p=>p.name=="Teacher")==1);Check("Every NPC has walk and idle animations",crowd.people.All(p=>p.legacyAnimation[p.idleClip]!=null&&p.legacyAnimation[p.walkClip]!=null));Check("Two complete desktop computer sets",all.Count(t=>t.name.StartsWith("Desktop computer "))==2&&all.Count(t=>t.name=="Keyboard")==2&&all.Count(t=>t.name=="Mouse")==2);
var old=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(Path.GetFullPath("../Documentation/SchoolExpansionPreflight.json")));var changed=new List<string>();foreach(var r in old["renderers"]){string path=(string)r["path"];if(!path.StartsWith("Classroom - licensed source art/"))continue;var go=GameObject.Find(path);if(!go){changed.Add(path+" missing");continue;}var p=r["pos"];var pos=new Vector3((float)p["x"],(float)p["y"],(float)p["z"]);if(Vector3.Distance(go.transform.position,pos)>.001f)changed.Add(path+" moved");var m=go.GetComponent<Renderer>().sharedMaterials.Select(AssetDatabase.GetAssetPath).ToArray();if(!m.SequenceEqual(r["materials"].Select(t=>(string)t)))changed.Add(path+" materials changed");}Check("Original classroom renderer positions and material references preserved",changed.Count==0,changed);nav.ResetNavigation();var json=Newtonsoft.Json.JsonConvert.SerializeObject(new{checks,routes},Newtonsoft.Json.Formatting.Indented);File.WriteAllText(Path.GetFullPath("../Documentation/SchoolSceneAudit.json"),json);return json;}}

